INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17401, 'Isaiah 43:7', 'Isaiah', 43, 7, '&nbsp;هغه څوک چې زما خپل خلق دى، کوم چې ما د دې دپاره پېدا کړى دى چې زما د جلال سبب جوړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17402, 'Isaiah 43:8', 'Isaiah', 43, 8, '&nbsp;هغه خلق راولئ د چا چې سترګې شته، خو هغوئ ړاندۀ دى، د چا چې غوږونه شته، خو هغوئ کاڼۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17403, 'Isaiah 43:9', 'Isaiah', 43, 9, '&nbsp;قومونه دې راغونډ شى. د هغوئ د معبودانو نه کوم يو د راتلونکى وخت پېشګوئې ورکولے شى؟ چې څۀ اوس کيږى نو کوم يو د دې په حقله مخکښې وئيلى وُو؟ هغه معبودان دې د دې ګواهان راولى چې دا ثابت شى چې هغوئ په حقه دى، او چې ګواهى ورکړى چې د هغوئ خبرې رښتيا دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17404, 'Isaiah 43:10', 'Isaiah', 43, 10, '&nbsp;مالِک خُدائ وفرمائيل، ”اے بنى اِسرائيلو، تاسو زما ګواهان يئ، زما خِدمت کوونکى يئ او ما غوره کړى يئ چې تاسو ما وپېژنئ او په ما به ايمان ولرئ او پته درته ولګى چې صرف زۀ خُدائ پاک يم. زما نه بغېر بل يو خُدائ هم نشته، نۀ د دې نه مخکښې وو او نۀ به د دې نه وروستو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17405, 'Isaiah 43:11', 'Isaiah', 43, 11, '&nbsp;زۀ، صرف زۀ مالِک خُدائ يم، او زما نه بغېر بل څوک خلاصونکے نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17406, 'Isaiah 43:12', 'Isaiah', 43, 12, '&nbsp;هم ما ستاسو د خلاصون اعلان وکړو او تاسو ته مې خلاصون درکړو، او دُنيا ته مې ښکاره کړو. او ستاسو په مينځ کښې بل يو غېر معبود هم داسې څۀ نۀ دى کړى، څۀ چې ما کړى دى.“ مالِک خُدائ فرمائى، ”تاسو زما ګواهان يئ چې زۀ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17407, 'Isaiah 43:13', 'Isaiah', 43, 13, '&nbsp;زۀ خُدائ پاک يم او د همېشه دپاره به يم. زما د طاقت نه هيڅ څوک هم نۀ شى بچ کېدلے، زۀ چې کوم کار کوم نو هغه څوک ايسارولے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17408, 'Isaiah 43:14', 'Isaiah', 43, 14, '&nbsp;د بنى اِسرائيلو مقدس ذات، هغه مالِک خُدائ چا چې تاسو بچ کړئ هغه فرمائى، ”ستاسو د بچ کولو دپاره، زۀ به د بابل خِلاف يو لښکر درولېږم، زۀ به د ښار دروازې راوغورزوم، او د دې د خلقو د خوشحالۍ چغې به په ژړا بدلې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17409, 'Isaiah 43:15', 'Isaiah', 43, 15, '&nbsp;زۀ مالِک خُدائ، ستاسو مقدس خُدائ پاک يم. زۀ د بنى اِسرائيلو خالق ستاسو بادشاه يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17410, 'Isaiah 43:16', 'Isaiah', 43, 16, '&nbsp;مالِک خُدائ فرمائى، ”ما په سمندر کښې يوه لار جوړه کړه، او د زورَورو اوبو په مينځ کښې مې يوه لار جوړه کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17411, 'Isaiah 43:17', 'Isaiah', 43, 17, '&nbsp;هغۀ يو طاقتور لښکر د تباهۍ طرف ته بوتلو، يو داسې لښکر چې جنګى ګاډۍ او آسونه يې لرل. هغوئ پرېوتل او بيا را پا نۀ څېدل، او د ډيوې د لمبې په شان ختم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17412, 'Isaiah 43:18', 'Isaiah', 43, 18, '&nbsp;”د تېر شوى وخت په واقعاتو پورې مۀ انښلئ او چې څۀ وړاندې شوى وى نو د هغې خيال د زړۀ نۀ وباسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17413, 'Isaiah 43:19', 'Isaiah', 43, 19, '&nbsp;زۀ چې کوم نوى کارونه کوم نو هغې ته ګورئ. هغه اوس شروع کېدو والا دى، تاسو يې نۀ وينئ څۀ؟ زۀ به په بيابان کښې يوه لار جوړه کړم او هلته به د اوبو نِهرونه جوړ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17414, 'Isaiah 43:20', 'Isaiah', 43, 20, '&nbsp;ځنګلى ځناور، ګيدړان او شتر‌مرغ به زما درناوے کوى، ځکه چې زۀ به په بيابان کښې اوبۀ ورکوم او په صحرا کښې به سيندونه روان کړم د دې دپاره چې خپلو خلقو له اوبۀ ورکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17415, 'Isaiah 43:21', 'Isaiah', 43, 21, '&nbsp;دا هغه خلق دى څوک چې ما د خپل ځان دپاره پېدا کړى دى، چې هغوئ زما ثناء صِفت وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17416, 'Isaiah 43:22', 'Isaiah', 43, 22, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، ستاسو زړۀ زما نه موړ شوے دے، او تاسو زما عبادت ونۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17417, 'Isaiah 43:23', 'Isaiah', 43, 23, '&nbsp;تاسو ما له د ګډو خپلې سوزېدونکې نذرانې رانۀ وړلې، تاسو د قربانو سره زما درناوے ونۀ کړو. په تاسو مې بوج وانۀ چولو چې نذرانې مې درنه غوښتے وے او تنګ مې نۀ کړئ چې خوشبودارې مصالحې مې درنه غوښتے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17418, 'Isaiah 43:24', 'Isaiah', 43, 24, '&nbsp;تاسو زما دپاره خوشبودارې مصالحې وانۀ خستلې او نۀ مو د خپلو ځناورو د وازګې سره خوشحاله کړم. خو تاسو په ما باندې ستاسو د ګناهونو بوج کېښودو، تاسو چې کوم بد عمل کړے دے د هغې په وجه مو تنګ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17419, 'Isaiah 43:25', 'Isaiah', 43, 25, '&nbsp;آو، زۀ هم هغه خُدائ پاک يم چې د خپل ځان په خاطر ستاسو په جرمونو پرده اچوم او ستاسو ګناهونه د خپل ذهن نه وباسم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17420, 'Isaiah 43:26', 'Isaiah', 43, 26, '&nbsp;راځئ چې عدالت ته لاړ شُو، خپل اِعتراض بيان کړئ. خپله خبره پېش کړئ چې ثابته شى چې تاسو په حقه يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17421, 'Isaiah 43:27', 'Isaiah', 43, 27, '&nbsp;ستاسو پلار نيکۀ ګناه وکړه، او ستاسو مشرانو زما خِلاف بغاوت وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17422, 'Isaiah 43:28', 'Isaiah', 43, 28, '&nbsp;نو په دې وجه به زۀ د مقدس ځائ مشران رسوا کړم او زۀ به بنى اِسرائيليان مکمل تباهۍ او شرم دپاره مخصوص کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17423, 'Isaiah 44:1', 'Isaiah', 44, 1, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، زما خِدمت کوونکو، اے د يعقوب اولاده، اے زما غوره کړے شوو خلقو اوس ماته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17424, 'Isaiah 44:2', 'Isaiah', 44, 2, '&nbsp;زۀ هغه مالِک خُدائ يم چا چې تاسو پېدا کړى يئ، د کوم وخت نه چې تاسو پېدا شوى يئ نو زۀ ستاسو مدد کوم. اے يعقوبه زما خادِمه، يرېږه مه، اے بنى اِسرائيله، تۀ ما غوره کړے يې، يرېږه مه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17425, 'Isaiah 44:3', 'Isaiah', 44, 3, '&nbsp;زۀ به تږى مُلک له اوبۀ ورکړم او په اوچه زمکه به نِهرونه روان کړم. زۀ به ستاسو په بچو خپل روح نازل کړم او ستاسو په اولاد به خپل برکتونه نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17426, 'Isaiah 44:4', 'Isaiah', 44, 4, '&nbsp;هغوئ به د داسې واښو په شان ترقى کوى چې سيرابه وى، د هغه خاروَلو ونو په شان چې د اوبو د روانو نِهرونو په غاړه شوې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17427, 'Isaiah 44:5', 'Isaiah', 44, 5, '&nbsp;خلق به وار په وار وائى چې، زۀ د مالِک خُدائ يم. هغوئ به راشى چې د بنى اِسرائيلو سره ملګرى شى. په هغوئ کښې به ځينې په خپل لاس د مالِک خُدائ نوم وليکى او خپل ځان به د خُدائ پاک د خلقو نه يو کس ګڼى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17428, 'Isaiah 44:6', 'Isaiah', 44, 6, '&nbsp;مالِک خُدائ، څوک چې په بنى اِسرائيلو حکومت کوى او د بنى اِسرائيلو حِفاظت کوى، هغه مالِک خُدائ ربُ الافواج داسې فرمائى، ”زۀ اولين او زۀ آخرين يم، زما نه بغېر بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17429, 'Isaiah 44:7', 'Isaiah', 44, 7, '&nbsp;زما په شان څوک دى؟ هغه دې آواز وکړى او خپل دليلونه دې پېش کړى. هغوئ دې په ترتيب سره ووائى څۀ چې د پخوا نه شوى دى چې کله ما خپل قوم قائم کړو. هغوئ دې د راتلونکى وخت د خبرو اعلان وکړى چې څۀ به کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17430, 'Isaiah 44:8', 'Isaiah', 44, 8, '&nbsp;مۀ يرېږئ، چې ونۀ يرېږئ. ولې ما تاسو ته ډېر مخکښې نۀ وُو وئيلى چې څۀ به کيږى؟ تاسو زما ګواهان يئ. بل خُدائ پاک شته څۀ؟ بل د پناه ځائ نشته چې زۀ ترې نه خبر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17431, 'Isaiah 44:9', 'Isaiah', 44, 9, '&nbsp;هر څوک چې بُتان جوړوى نو هغوئ هيڅ هم نۀ دى او چې کومو څيزونو ته هغوئ ډېر زيات خوشحاليږى هغه بې‌فائدې دى. د بُت پرستانو نۀ خو سترګې شته او نۀ پکښې عقل شته خو آخر به هم د شرم سره مخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17432, 'Isaiah 44:10', 'Isaiah', 44, 10, '&nbsp;هغه څوک دے چې ځان له يوه مجسمه يا بُت جوړوى او د هغې به ورته هيڅ فائده نۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17433, 'Isaiah 44:11', 'Isaiah', 44, 11, '&nbsp;ګورئ، هغوئ او د هغوئ ټول ملګرى به وشرميږى. کوم خلق چې بُتان جوړوى هغوئ صرف انسانان دى. هغوئ دې راشى او په عدالت کښې دې پېش شى، هغوئ به ويريږى او د شرم سره به مخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17434, 'Isaiah 44:12', 'Isaiah', 44, 12, '&nbsp;لوهار د اوسپنې يوه تکړه واخلى او د سکروټو په ذريعه په دې باندې کار کوى. هغه د مټو زور سره څټک وهى او د دې نه يو بُت جوړ کړى. هغه اوږے شى او د لوږې نه يې طاقت جواب ورکړى او د تندې نه يې رنګ زېړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17435, 'Isaiah 44:13', 'Isaiah', 44, 13, '&nbsp;ترکاڼ د لرګى ناپ واخلى. هغه په دې باندې کرښې وهى، دا لرګے د خپل آوزار سره وتراشى او د يو بنى آدم شکل ترې نه جوړ کړى، چې د يو انسان په شان ښائسته صورت لرى، د دې دپاره چې په يو بُت‌خانه کښې يې ولګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17436, 'Isaiah 44:14', 'Isaiah', 44, 14, '&nbsp;کاريګر د دِيار ونې ووهى چې د هغې نه کار واخلى، يا د ځنګل د څېړۍ ونه يا د دِيار ونه خوښه کړى. يا هغه د نختر ونه وکَرى او د باران سره دا را غټه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17437, 'Isaiah 44:15', 'Isaiah', 44, 15, '&nbsp;يو کس به د ونې څۀ حِصه د خشاک دپاره استعمال کړى او د څۀ حِصې نه به يې اور بل کړى چې خپل ځان پرې تود کړى او روټۍ ورباندې پخه کړى. او دا هم يو حقيقت دے چې د څۀ حِصې نه به يې يو بُت جوړ کړى او عبادت به يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17438, 'Isaiah 44:16', 'Isaiah', 44, 16, '&nbsp;هغه د څۀ لرګو نه اور بل کړى، هغه ورباندې غوښه سره کړى، وې خورى او موړ شى. هغه ورباندې خپل ځان تود کړى او وائى، ”دا څومره تود او زبردست اور دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17439, 'Isaiah 44:17', 'Isaiah', 44, 17, '&nbsp;کوم لرګے چې پاتې شى نو د هغې نه يو بُت جوړ کړى او بيا ورته هغه ټيټيږى او عبادت يې کوى. هغه دې ته سوال کوى او ورته وائى، ”تۀ زما خُدائ يې، تۀ ما بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17440, 'Isaiah 44:18', 'Isaiah', 44, 18, '&nbsp;داسې خلقو ته هيڅ پته نۀ وى او نۀ په څۀ پوهيږى. د هغوئ په سترګو او زړونو باندې پرده پرته وى، نو په دې وجه نۀ هغوئ څۀ وينى او نۀ په څۀ پوهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17441, 'Isaiah 44:19', 'Isaiah', 44, 19, '&nbsp;د بُتانو جوړونکى دومره عقل او پوهه نۀ لرى چې سوچ پرې وکړى چې، ”څۀ لرګى ما وسوزول. د څۀ سره مې روټۍ پخه کړه او د دې په سکارو مې غوښه سره کړه او ومې خوړه. نو د دې پاتې لرګى نه به زۀ بُت جوړوم او دې ته به زۀ سجده کوم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17442, 'Isaiah 44:20', 'Isaiah', 44, 20, '&nbsp;دا داسې دى لکه چې څوک ايرې خورى. هغه خپلو کم عقلو سوچونو بې‌لارې کړے دے. هغه به په خپل زړۀ کښې دا خبره هم نۀ اچوى چې، ”زما په لاس کښې چې کوم بُت دے هغه په رښتيا خُدائ نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17443, 'Isaiah 44:21', 'Isaiah', 44, 21, '&nbsp;مالِک خُدائ فرمائى، ”اے بنى اِسرائيلو، دا خبره ياده ساتئ، تاسو زما خِدمت کوونکى يئ. ما تاسو د دې دپاره پېدا کړئ چې زما خِدمت کوونکى يئ، او زۀ به تاسو هيڅکله نۀ هېروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17444, 'Isaiah 44:22', 'Isaiah', 44, 22, '&nbsp;ما ستاسو ګناهونه د وريځې په شان لرې کړې دى. ما ستاسو ګناهونه داسې لرې کړې دى لکه چې نمر سخت دُهند لرې کوى. ما له راواپس شئ، زۀ هغه ذات يم څوک چې تاسو بچ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17445, 'Isaiah 44:23', 'Isaiah', 44, 23, '&nbsp;اے آسمانونو، د خوشحالۍ نه چغې ووهئ، ځکه چې مالِک خُدائ هر څۀ وکړل. د زمکې ژورو ځايونو، چغې ووهئ. غرونو او د ځنګل هرې ونې، د خوشحالۍ نه چغې ووهئ. مالِک خُدائ خپل خلق بنى اِسرائيليان بچ کړل او خپله لوئى يې وښودله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17446, 'Isaiah 44:24', 'Isaiah', 44, 24, '&nbsp;مالِک خُدائ ستاسو خلاصونکے فرمائى، ”زۀ هغه ذات يم چا چې تاسو پېدا کړى يئ. زۀ مالِک خُدائ يم، ما دا هر څيز پېدا کړے دے. ما په يواځې ځان په زمکه باندې آسمانونه ودرول، او زمکه مې پخپله خوره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17447, 'Isaiah 44:25', 'Isaiah', 44, 25, '&nbsp;زۀ د دروغو نبوت کوونکى دروغژن ثابتوم، او د فالګرو نه کم عقلان جوړوم. زۀ د هوښيارانو خلقو خبرې غلطى ثابتوم او د هغوئ حِکمت په کم عقلتوب بدلوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17448, 'Isaiah 44:26', 'Isaiah', 44, 26, '&nbsp;زۀ د خپلو خِدمت کوونکو پېشګويانې پوره کوم او د خپلو پېغمبرانو منصوبې سر ته رسوم. زۀ د يروشلم په حقله وايم چې خلق به بيا هلته اوسيږى، او د يهوداه ښارونو ته وايم چې دا به بيا جوړ شى. او دا به د کنډرو نه په ښارونو بدل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17449, 'Isaiah 44:27', 'Isaiah', 44, 27, '&nbsp;هم زۀ ژور سمندر ته حُکم ورکوم چې، اوچ شه، زۀ ستا ژوروالے اوچوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17450, 'Isaiah 44:28', 'Isaiah', 44, 28, '&nbsp;زۀ خورس ته وايم، تۀ زما شپون يې، تۀ به هغه کار کوې چې څۀ درته زۀ وايم يعنې، تۀ به حُکم ورکړې چې يروشلم دې بيا جوړ شى او د خُدائ پاک د کور بنيادونه دې واچولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17451, 'Isaiah 45:1', 'Isaiah', 45, 1, '&nbsp;مالِک خُدائ خپل غوره کړے شوے خادِم خورس ته فرمائى، ”ما ستا ښے لاس نيولے دے، نو ځکه چې تۀ هر چرته ځې هلته به قومونه ستا تابع کړم، د بادشاهانو زور به ختم کړم، د ښارونو دروازې به ستا دپاره کولاو کړم او بندوم به يې نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17452, 'Isaiah 45:2', 'Isaiah', 45, 2, '&nbsp;زۀ به په خپله ستا نه وړاندې ځم، او غرونه به درته هوار کړم. زۀ به د زېړو دروازې راوغورزوم او د دې د اوسپنې سيخونه به ټوټې ټوټې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17453, 'Isaiah 45:3', 'Isaiah', 45, 3, '&nbsp;زۀ به تا له د تورې تيارې او د پټو ځايونو نه خزانې درکړم، نو بيا به تا ته پته ولګى چې زۀ مالِک خُدائ يم، او چې د بنى اِسرائيلو خُدائ پاک يم څوک چې تا ته په نوم آواز کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17454, 'Isaiah 45:4', 'Isaiah', 45, 4, '&nbsp;زما د خِدمت کوونکو او غوره کړے شوو بنى اِسرائيلو د خاطره، زۀ تا ته په نوم آواز کوم او تا له مې د لوئ عزت لقب درکړے دے، اګر چې تۀ ما نۀ پېژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17455, 'Isaiah 45:5', 'Isaiah', 45, 5, '&nbsp;زۀ مالِک خُدائ يم، بل يو خُدائ هم نشته. زۀ تا له طاقت درکوم، اګر چې تۀ ما نۀ پېژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17456, 'Isaiah 45:6', 'Isaiah', 45, 6, '&nbsp;دا زۀ د دې دپاره کوم چې د دُنيا د يو سر نه تر بل سره پورې هر چا ته پته ولګى چې زۀ مالِک خُدائ يم او بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17457, 'Isaiah 45:7', 'Isaiah', 45, 7, '&nbsp;زۀ رڼا او تيارۀ دواړه پېدا کوم، سلامتى او بربادى دواړه زۀ راولم. زۀ، مالِک خُدائ دا هر څۀ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17458, 'Isaiah 45:8', 'Isaiah', 45, 8, '&nbsp;اے آسمانه باران ووروه او زمکه تازه کړه. اے وريځو، صداقت راوروئ. زمکه دې دا جذب کړى چې خلاصون راوټوکيږى او دې سره صداقت هم راوټوکيږى. ما، مالِک خُدائ دا پېدا کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17459, 'Isaiah 45:9', 'Isaiah', 45, 9, '&nbsp;په هغۀ باندې افسوس چې د خپل خالق سره جګړه کوى، هغه داسې دے لکه چې د ماتو لوښو يو ټيکرے وى. ولې خټه د کُلال نه تپوس کوى څۀ چې، ”تۀ څۀ جوړوې؟“ ولې ستا کوم جوړ شوے څيز ستا په حقله شکايت کوى څۀ؟ د هغۀ هيڅ اختيار نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17460, 'Isaiah 45:10', 'Isaiah', 45, 10, '&nbsp;په هغۀ باندې افسوس چې خپل پلار ته وائى چې، ”زۀ دې ولې پېدا کړم؟“ يا خپلې مور ته ووائى چې، ”تا ولې زۀ داسې جوړ کړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17461, 'Isaiah 45:11', 'Isaiah', 45, 11, '&nbsp;مالِک خُدائ، د بنى اِسرائيلو مقدس ذات، کوم ذات چې هغوئ پېدا کړى دى، هغه وائى، ”تاسو څنګه زما د بچو په حقله ما نه تپوس کولے شئ؟ څۀ چې ما جوړ کړى دى د هغې په حقله تاسو څنګه ما له حُکم راکولے شئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17462, 'Isaiah 45:12', 'Isaiah', 45, 12, '&nbsp;زۀ هغه ذات يم چا چې زمکه پېدا کړه، ما بنى آدم پېدا کړل چې هلته اوسيږى. ما د خپل طاقت په ذريعه آسمانونه خوارۀ کړل، او هم ما په آسمان کښې ټول ستورى جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17463, 'Isaiah 45:13', 'Isaiah', 45, 13, '&nbsp;ما په خپله خورس راپاڅولے دے چې واک اختيار په لاس کښې واخلى او زما مقصد پوره کړى او کارونه سم کړى. زۀ به هم د هغۀ ټولې لارې سيدها کوم. هغه به زما ښار بيا جوړ کړى، او زما خلق به د قېد نه آزاد کړى. هغه به دا هر څۀ مفت کوى، نۀ به پېسې اخلى او نۀ تحفې.“ مالِک خُدائ ربُ الافواج دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17464, 'Isaiah 45:14', 'Isaiah', 45, 14, '&nbsp;مالِک خُدائ فرمائى، ”د مِصر او ايتهوپيا مال دولت به ستاسو وى، او د سبائيانو لوَړ لوَړ سړى به ستاسو غلامان وى، هغوئ به په تاسو پسې په زنځيرونو کښې روان وى. هغوئ به تاسو ته ټيټ شى او اِقرار به وکړى چې، خُدائ پاک ستاسو مل دے، صرف هغه خُدائ پاک دے. د هغۀ نه بغېر بل خُدائ نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17465, 'Isaiah 45:15', 'Isaiah', 45, 15, '&nbsp;بې‌شکه تۀ هغه خُدائ يې څوک چې ځان پټ ساتى، اے د بنى اِسرائيلو خُدائ پاکه، خلاصونکيه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17466, 'Isaiah 45:16', 'Isaiah', 45, 16, '&nbsp;څوک چې بُتان جوړوى نو هغوئ به د شرم سره مخ شى، او هغوئ ټول به سپک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17467, 'Isaiah 45:17', 'Isaiah', 45, 17, '&nbsp;خو مالِک خُدائ د بنى اِسرائيلو مُلک بچ کوى، د يو نۀ ختمېدونکى خلاصون سره. او د دې خلق به کله تر آخره پورې هم بې‌عزته نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17468, 'Isaiah 45:18', 'Isaiah', 45, 18, '&nbsp;مالِک خُدائ فرمائى، ”زۀ مالِک خُدائ يم، او بل يو خُدائ هم نشته.“ څوک چې دا وائى هغه خُدائ پاک دے. چا چې آسمانونه پېدا کړى دى، دا هغه ذات دے کوم چې زمکه پېدا کړه او جوړه يې کړه، او زمکه خوشې او شاړه پاتې نۀ شوه بلکې هغۀ دا د اوسېدلو قابله جوړه کړه، چې ژوندے مخلوق په کښې اوسيږى. مالِک خُدائ فرمائى، ”زۀ مالِک خُدائ يم ما نه غېر بل مالِک نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17469, 'Isaiah 45:19', 'Isaiah', 45, 19, '&nbsp;ما څۀ په پټ ځائ کښې پټې خبرې نۀ دى کړې. او نۀ مې بنى اِسرائيلو ته دا وئيلى دى چې، ”بې‌شکه ما لټوئ، خو تاسو به ما مومئ نه.“ زۀ، مالِک خُدائ يم او زۀ رښتيا وايم، او څۀ چې صحيح وى نو زۀ د هغې اعلان کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17470, 'Isaiah 45:20', 'Isaiah', 45, 20, '&nbsp;”هغه ټول خلق چې د بادشاه د زوال نه پس ژوندى پاتې يئ، راغونډ شئ، خپل ځانونه زما حضور کښې پېش کړئ. څوک چې ځان سره د لرګى بُتان ګرځوى هغوئ په هيڅ هم نۀ پوهيږى. چې کوم معبودان خلاصون نۀ شى ورکولے نو د هغوئ نه دُعا ولې غواړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17471, 'Isaiah 45:21', 'Isaiah', 45, 21, '&nbsp;راشئ او خپله مقدمه په عدالت کښې پېش کړئ، بې‌شکه اول د يو بل سره مشوره وکړئ. ډېر پخوا دا پېشګوئې چا ورکړې وه؟ ولې ما مالِک خُدائ ډېره موده مخکښې دا اعلان نۀ وو کړے؟ ځکه چې بغېر زما نه بل يو خُدائ هم نشته. زۀ خلاصونکے او صادق خُدائ يم. زما نه بغېر بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17472, 'Isaiah 45:22', 'Isaiah', 45, 22, '&nbsp;اے د ټولې دُنيا خلقو، اوس ما ته راوګرځئ او خلاصون حاصل کړئ. صرف زۀ خُدائ پاک يم او زما نه بغېر بل يو خُدائ هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17473, 'Isaiah 45:23', 'Isaiah', 45, 23, '&nbsp;زما وعده رښتيا ده، او زما وعده به نۀ بدليږى. ما په خپل ذات باندې قسم خوړلے دے، چې هره يوه ګوډه به ما ته په سجده شى او هره ژبه به اِقرار وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17474, 'Isaiah 45:24', 'Isaiah', 45, 24, '&nbsp;او وائى به چې فتح او طاقت صرف د مالِک خُدائ په ذريعه ملاويږى، خو هغه ټول څوک چې زما نه نفرت کوى نو هغوئ به زما حضور ته راشى او شرم سره به مخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17475, 'Isaiah 45:25', 'Isaiah', 45, 25, '&nbsp;خو د اِسرائيل ټول اولاد به د مالِک خُدائ په نظر کښې صادقان شى او په هغۀ به فخر کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17476, 'Isaiah 46:1', 'Isaiah', 46, 1, '&nbsp;د بابل د معبودانو بيل او نبو سرونه ښکته وُو کله چې دوئ راکوز کړے شول، او اوس هغه په ځناورو باندې بار دى، چې د ستړى شوو ځناورو دپاره بوج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17477, 'Isaiah 46:2', 'Isaiah', 46, 2, '&nbsp;دا دواړه معبودان ټيټ شول او پړمخې پرېوتل. هغوئ د بوج جوړېدو نه بچ پاتې نۀ شول او اوس په خپله جلاوطن شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17478, 'Isaiah 46:3', 'Isaiah', 46, 3, '&nbsp;”اے د يعقوب اولاده، ما ته غوږ ونيسئ، اے په بنى اِسرائيلو کښې زما باقى پاتې شوو ټولو خلقو. د مور د خېټې نه ما ستاسو پالنه کړې ده، چې کله تاسو پېدا شوى يئ نو د هغې وخت نه زۀ په تاسو پام کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17479, 'Isaiah 46:4', 'Isaiah', 46, 4, '&nbsp;زۀ ستاسو خُدائ پاک يم او زۀ به ستاسو ساتنه کوم چې تاسو بوډاګان او سپين سَرى هم شئ. نو ما تاسو پېدا کړى يئ او ستاسو خيال به ساتم، زۀ به ستاسو ملاتړ يم او تاسو به بچ کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17480, 'Isaiah 46:5', 'Isaiah', 46, 5, '&nbsp;مالِک خُدائ فرمائى، ”تاسو به ما د چا سره برابروئ؟ زما په شان بل څوک شته څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17481, 'Isaiah 46:6', 'Isaiah', 46, 6, '&nbsp;خلق خپلې کڅوړې کولاو کړى او سرۀ زر ترې نه غورزوى، هغوئ په تله سپين زر تلى. هغوئ زرګر له پېسې ورکړى چې يو بُت ورله جوړ کړى، او بيا ورته ټيټيږى او عبادت يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17482, 'Isaiah 46:7', 'Isaiah', 46, 7, '&nbsp;هغوئ دا خپلو اوږو ته اوچت کړى او يو خوا او بل خوا يې وړى راوړى، او بيا په يو ځائ کښې يې کېږدى او هلته ولاړ وى، خو چې چرته وى نو د هغه ځائ نه حرکت نۀ شى کولے. کۀ څوک دې ته په چغو فرياد وکړى، نو دا جواب نۀ ورکوى او نۀ هغه کس د مصيبت نه بچ کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17483, 'Isaiah 46:8', 'Isaiah', 46, 8, '&nbsp;اے ګناهګارانو، دا ياد ساتئ، او چې ما څۀ کړى دى هغه مۀ هېروئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17484, 'Isaiah 46:9', 'Isaiah', 46, 9, '&nbsp;هغه راياد کړئ چې ډېره موده مخکښې شوى وُو، ځکه چې صرف زۀ خُدائ پاک يم او زما په شان بل هيڅ څوک هم نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17485, 'Isaiah 46:10', 'Isaiah', 46, 10, '&nbsp;د شروع نه ما د اَنجام پېشګوئې ورکوله، ما ډېر پخوا وئيلى دى چې څۀ کېدونکى دى. ما وئيل چې زما منصوبې به نۀ ناکامه کيږى، او چې زۀ به هغه هر يو کار کوم چې ما يې اراده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17486, 'Isaiah 46:11', 'Isaiah', 46, 11, '&nbsp;زۀ د نمرخاتۀ طرف نه يو ښکارى مارغۀ راغواړم، د لرې مُلک نه به يو داسې سړے راشى چې زما منصوبه به پوره کوى. څۀ چې ما وئيلى دى زۀ به هغه سر ته رسوم. او چې کومه منصوبه ما جوړه کړې وى هغه به سر ته رسوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17487, 'Isaiah 46:12', 'Isaiah', 46, 12, '&nbsp;اے ضدى خلقو، ما ته غوږ ونيسئ څوک چې د خلاصون نه ډېر لرې يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17488, 'Isaiah 46:13', 'Isaiah', 46, 13, '&nbsp;ما خپل خلاصون نزدې راوړے دے، هغه لرې نۀ دے. زما خلاصون راتلو کښې به وخت نۀ لګى. زۀ به يروشلم بچ کړم او بنى اِسرائيلو ته به خپل شان او شوکت وښايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17489, 'Isaiah 47:1', 'Isaiah', 47, 1, '&nbsp;اے د پېغلې په شان بابله، د خپل تخت نه راکوز شه، او په زمکه په خاورو کښې کښېنه. ځکه چې ستا په تخت د ناستې وخت ختم دے. اے بابله، تۀ به بيا د شهزادګۍ په شان نرم او نازک نۀ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17490, 'Isaiah 47:2', 'Isaiah', 47, 2, '&nbsp;د ژرندې کاڼے واخله او اوړۀ مېده کړه. نقاب لرې کړه، خپلې ښائسته جامې وباسه، پېنڅې اوچتې کړه چې د نِهرونو نه پورې وځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17491, 'Isaiah 47:3', 'Isaiah', 47, 3, '&nbsp;خلق به تا وګورى چې بربنډ يې، هغوئ به ستا شرمګاه وګورى. زۀ به بدله واخلمه او هيڅ څوک به نۀ پرېږدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17492, 'Isaiah 47:4', 'Isaiah', 47, 4, '&nbsp;د بنى اِسرائيلو مقدس ذات مونږ په بيعه اخستى يُو، د هغۀ نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17493, 'Isaiah 47:5', 'Isaiah', 47, 5, '&nbsp;اے د بابليانو لورې، په تيارۀ کښې خاموش کښېنه، نور به تا ته څوک د قومونو مَلِکه نۀ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17494, 'Isaiah 47:6', 'Isaiah', 47, 6, '&nbsp;زۀ خپلو خلقو ته غصه وم، ما هغوئ له داسې سزا ورکړه چې تا ته مې حواله کړل. او تا په هغوئ باندې هيڅ رحم ونۀ کړو، او په بوډاګانو دې هم ډېر دروند بوج کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17495, 'Isaiah 47:7', 'Isaiah', 47, 7, '&nbsp;تا وئيل، ”زۀ به همېشه مَلِکه يم.“ او هيڅکله دې فکر نۀ دے کړے او نۀ دې د دې په اَنجام باندې غور وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17496, 'Isaiah 47:8', 'Isaiah', 47, 8, '&nbsp;نو اوس دا خبره واوره، اے د عېش سره مينه لرونکې، تۀ خپل ځان محفوظ ګڼې او وائې، ”هم زۀ يم. او زما نه بغېر بل څوک نشته. زۀ به نۀ کله کونډه شم او نۀ بې‌اولاده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17497, 'Isaiah 47:9', 'Isaiah', 47, 9, '&nbsp;خو په يوه لحظه او هم په يوه ورځ کښې به دا دواړه کارونه درسره وشى. تۀ چې هر څومره د جادو نه کار واخلې، خو ستا خاوند او بچى به ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17498, 'Isaiah 47:10', 'Isaiah', 47, 10, '&nbsp;تا خپل ځان په بدعملۍ کښې محفوظ وګڼلو، ستا خيال دا وو چې هيڅ څوک دې نۀ وينى. خپل حِکمت او پوهې تۀ بې‌لارې کړې، او تا د خپل ځان سره ووئيل چې، ”هم زۀ يم. او زما نه بغېر بل څوک نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17499, 'Isaiah 47:11', 'Isaiah', 47, 11, '&nbsp;داسې افت به په تا راشى، چې ستا يو جادو منتر به هم دا منع کولے نۀ شى. تباهى به په تا باندې راشى او هيڅ منښته به دا بندولے نۀ شى. وبا به په تا باندې ناڅاپه راشى، او تۀ به د هغې دپاره تياره نۀ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17500, 'Isaiah 47:12', 'Isaiah', 47, 12, '&nbsp;خپل جادو او کوډې ځان سره وساته، تا د وړوکوالى نه دا استعمال کړى دى. کېدے شى چې دا ستا دپاره مددګار ثابت شى، او تۀ په دې خپل دشمنان ويروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');